mapper.select:
SELECT spc.id, spcd.id AS changeDetailId, spc.code, spc.create_user_id AS createUserId, spc.create_user_name AS createUserName, spc.create_time AS createTime, spcd.customer_id AS customerId, ci.name AS customerId, spcd.sku_id AS skuId, spcd.sku_no AS skuNo, spcd.min_qty AS minQty, spcd.max_qty AS maxQty, spc.approve_status AS approveStatus, spcd.tax_price AS taxPrice, spcd.currency, spcd.tax_rate * 100 AS taxRate , spcd.effective_date AS effectiveDate, spcd.expire_date AS expireDate, spc.so_org_id AS soOrgId, spc.so_org_name AS soOrgName, spcd.disabled, spcd.so_price_detail_id as soPriceDetailId, spcd.remark as detailRemark, spc.approve_time FROM so_price_change_detail spcd INNER JOIN so_price_change spc ON spcd.main_id = spc.id and spc.is_deleted = false inner join customer_info ci on ci.id = spcd.customer_id and ci.is_deleted = false WHERE ${params.sqlMap.default} AND spcd.is_deleted= false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spc.create_time DESC,spcd.id DESC

SELECT spc.id, spcd.id AS changeDetailId, spcd.so_price_detail_id, spc.code, spc.create_user_id AS createUserId, spc.create_user_name AS createUserName, spc.create_time AS createTime, spcd.customer_id AS customerId, ci.name AS customerId, spcd.sku_id, spcd.sku_no, spcd.min_qty, spcd.max_qty, spc.approve_status, spcd.tax_price, spcd.currency, spcd.tax_rate * 100 AS taxRate , spcd.effective_date, spc.so_org_id, spc.so_org_name, spcd.disabled, spcd.remark as detailRemark, spc.approve_time FROM so_price_change_detail spcd INNER JOIN so_price_change spc ON spcd.main_id = spc.id and spc.is_deleted = false left join customer_info ci on ci.id = spcd.customer_id and ci.is_deleted = false WHERE ${params.sqlMap.default} AND spcd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spc.create_time DESC,spcd.id DESC

select count(distinct spc.id) from so_price_change spc left join so_price_change_detail spcd on spc.id = spcd.main_id and spcd.is_deleted = false
${params.sqlMap.default} and spc.is_deleted = false
${params.permissionSql}
